INSERT INTO `categories` (`id`, `parent_id`, `name`, `slug`, `tagline`, `description`, `meta_title`, `meta_desc`, `image`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES
  ('1', NULL, 'Rider', 'rider', 'Rider Apparel & Gear', 'Everything worn in the saddle - engineered for the arena, the gallop and the long safari ride.', 'Rider Apparel & Riding Gear', 'Riding boots, breeches, jackets, gloves and helmets for every discipline. Rider apparel from Tack Rack, Nairobi — fitted advice from staff who ride.', NULL, '1', '1', '2026-08-18 14:03:18', '2026-08-18 16:11:14'),
  ('2', NULL, 'Horse', 'horse', 'Horse Equipment (Tack)', 'Saddlery and tack selected, fitted and maintained by qualified specialists.', 'Horse Tack & Saddlery', 'Saddles, bridles, bits, reins, numnahs and rugs. Professionally fitted saddlery in Nairobi from Kenya\'s equestrian supplier since 1997.', NULL, '2', '1', '2026-08-18 14:03:18', '2026-08-18 16:11:14'),
  ('3', NULL, 'Stable', 'stable', 'Yard, Grooming & Care', 'The quiet essentials that keep a yard running and leather living for decades.', 'Stable, Grooming & Leather Care', 'Grooming kits, stable equipment and leather care for the Kenyan climate. Everything that keeps a yard running and tack lasting.', NULL, '3', '1', '2026-08-18 14:03:18', '2026-08-18 16:11:14'),
  ('10', '1', 'Footwear', 'footwear', 'Short Boots, Paddock Boots & Chaps', NULL, 'Riding Boots, Paddock Boots & Chaps', 'Short boots, paddock boots and half chaps in full-grain leather. Sized and stocked for Kenyan riders at Tack Rack, Ngong Road.', NULL, '1', '1', '2026-08-18 14:03:18', '2026-08-18 16:32:12'),
  ('11', '1', 'Riding Jackets & Vests', 'riding-jackets-vests', 'Show & Schooling Outerwear', 'Competition jackets, softshells and body protectors cut for a correct riding position.', 'Body Protectors & Riding Jackets', 'BETA-certified body protectors, competition jackets and schooling vests, fitted in person at Tack Rack, Ngong Road, Nairobi.', NULL, '2', '1', '2026-08-18 14:03:18', '2026-08-30 22:09:03'),
  ('12', '1', 'Breeches & Tights', 'breeches-tights', 'Full Seat, Knee Patch & Performance', 'Grip, stretch and breathability for schooling in the Kenyan sun.', 'Breeches, Jodhpurs & Riding Tights', 'Show breeches, schooling jodhpurs and full-seat tights for adults and children. Sized in person at Tack Rack, Ngong Road, Nairobi.', NULL, '3', '1', '2026-08-18 14:03:18', '2026-08-30 22:09:03'),
  ('13', '1', 'Gloves & Accessories', 'gloves-accessories', 'Hands, Head & Detail', 'Gloves, helmets, crops, spurs, belts and the small things that finish a turnout.', 'Gloves, Whips & Riding Accessories', 'Riding gloves, hat silks, schooling whips, lunge whips and number holders — the small things that finish a turnout. In Nairobi.', NULL, '4', '1', '2026-08-18 14:03:18', '2026-08-30 22:09:03'),
  ('20', '2', 'Saddles & Accessories', 'saddles-accessories', 'Jumping, Dressage, GP & Polo', 'Fitted by the only Society of Master Saddlers qualified fitter in East Africa.', 'Saddles & Saddle Accessories', 'Jumping, dressage, general purpose and polo saddles, fitted on the horse by the only Society of Master Saddlers qualified fitter in East Africa.', NULL, '1', '1', '2026-08-18 14:03:18', '2026-08-18 16:11:14'),
  ('21', '2', 'Bridles, Bits & Reins', 'bridles-bits-reins', 'Contact & Communication', 'Anatomical bridles, stainless bits and reins in rubber, web and plaited leather.', 'Bridles, Bits & Reins', 'Anatomical bridles, stainless steel bits and leather reins. Correct contact starts with the right bit — advice included.', NULL, '2', '1', '2026-08-18 14:03:18', '2026-08-18 16:11:14'),
  ('22', '2', 'Saddle Pads & Blankets', 'saddle-pads-blankets', 'Numnahs, Squares & Rugs', 'Including numnahs and rugs manufactured in our own Nairobi workshop.', 'Numnahs, Saddle Pads & Blankets', 'Quilted GP numnahs, dressage squares and saddle blankets in every colour. Shaped to sit clear of the withers. Stocked in Nairobi.', NULL, '3', '1', '2026-08-18 14:03:18', '2026-08-30 22:09:03'),
  ('23', '2', 'Halters & Lead Ropes', 'halters-lead-ropes', 'Handling & Turnout', 'Leather and webbing headcollars with matched lead ropes.', 'Headcollars, Halters & Lead Ropes', 'Leather and webbing headcollars, halters and lead ropes for the yard and the lorry. From Tack Rack, Ngong Road, Nairobi.', NULL, '4', '1', '2026-08-18 14:03:18', '2026-08-30 22:09:03'),
  ('24', '2', 'Horse Health & Supplements', 'horse-health-supplements', 'Feed Balancers & Veterinary Care', 'Supplements, wound care and electrolytes for hard-working horses.', 'Horse Health & Feed Supplements', 'Electrolytes, hoof and joint supplements and first aid for the tack room. Advice from staff who keep horses in Kenya themselves.', NULL, '5', '1', '2026-08-18 14:03:18', '2026-08-30 22:09:03'),
  ('30', '3', 'Grooming Kits & Supplies', 'grooming-kits-supplies', 'Brushes, Combs & Coat Care', 'Complete kits and individual brushes for a show-ready coat.', 'Grooming Kits, Brushes & Supplies', 'Body brushes, dandy brushes, curry combs, mane combs and tack boxes. Everything for a proper grooming kit, stocked in Nairobi since 1997.', NULL, '1', '1', '2026-08-18 14:03:18', '2026-08-30 22:09:03'),
  ('31', '3', 'Stable Equipment', 'stable-equipment', 'Yard Hardware', 'Buckets, mangers, forks, haynets and the fittings that outlast a season.', 'Stable & Yard Equipment', 'Tack boxes, buckets and the everyday kit that keeps a yard running. Chosen to survive Kenyan yards, stocked in Nairobi since 1997.', NULL, '2', '1', '2026-08-18 14:03:18', '2026-08-30 22:09:03'),
  ('32', '3', 'Leather Care & Maintenance', 'leather-care-maintenance', 'Preserving the Investment', 'Balms, soaps and oils - essential in a dry, high-altitude climate.', 'Leather Care & Tack Cleaning', 'Balms, saddle soaps and oils that keep leather alive in a dry, high-altitude climate. The single most important thing you can buy for your tack.', NULL, '3', '1', '2026-08-18 14:03:18', '2026-08-18 16:11:14'),
  ('33', '1', 'Helmets & Head Protection', 'helmets-head-protection', 'Hats, Skull Caps & Silks', 'Riding hats, skull caps and silks — fitted properly, because a hat that moves cannot do its job.', 'Riding Hats, Helmets & Skull Caps', 'Riding helmets, velvet show hats, skull caps and hat silks, fitted in person at Tack Rack, Ngong Road, Nairobi.', NULL, '5', '1', '2026-08-30 20:15:33', '2026-08-30 20:15:33');
